SELECT jsonb_build_object('customer',(SELECT count(*) FROM app.customer_profiles WHERE id='1231a676-4ed8-535a-8c2b-8243befd0ab8'),'command',(SELECT count(*) FROM platform.runtime_command_receipt WHERE id IN ('ae6b8d13-26f4-50be-b0d1-2902ac1c5146','7c98ed9d-9d9f-5339-89d8-92d3be059ebe')), 'history',(SELECT count(*) FROM app.customer_profile_lifecycle_event WHERE customer_profile_id='1231a676-4ed8-535a-8c2b-8243befd0ab8'),'evidence',(SELECT count(*) FROM platform.owner_mutation_evidence WHERE aggregate_kind='CustomerProfile' AND aggregate_id='1231a676-4ed8-535a-8c2b-8243befd0ab8'),'outbox',(SELECT count(*) FROM platform.runtime_outbox_message WHERE command_receipt_id IN ('ae6b8d13-26f4-50be-b0d1-2902ac1c5146','7c98ed9d-9d9f-5339-89d8-92d3be059ebe')),'track_enrollments',(SELECT count(*) FROM app.track_enrollment_receipt WHERE profile_id='1231a676-4ed8-535a-8c2b-8243befd0ab8'),'coherent',EXISTS(SELECT 1 FROM app.customer_profiles c
