  AND q.result_body='{"contract":"SH-004.v1","requestId":"customer-04-missing-free","status":"ok","value":{"customerProfileId":"1231a676-4ed8-535a-8c2b-8243befd0ab8","userId":"e76d13b8-de8f-509f-85df-016eda48ec10","lifecycle":"active","sourceToken":"0","receipt":{"owner":"customer_buyer_profile","id":"ae6b8d13-26f4-50be-b0d1-2902ac1c5146","semanticKey":"customer-controls-customer-04-missing-free","fingerprint":"92f3e8344af33a6177054c7c05dde1f7b286f11f92005aa11d83148a1191cf80","sourceToken":"0","recordedAt":"2026-11-17T00:00:00Z"}}}'::jsonb AND q.result_digest=encode(sha256(convert_to(q.result_body::text,'UTF8')),'hex')
 JOIN app.customer_profile_lifecycle_event h ON h.id='3fd5de71-5f1a-548d-8885-31c058905342' AND h.customer_profile_id=c.id AND h.command_receipt_id=q.id
  AND h.source_revision=0 AND h.from_status IS NULL AND h.to_status=c.status AND h.actor_user_id=c.user_id AND h.name='customer.lifecycle_changed.v1'
 JOIN platform.owner_mutation_evidence e ON e.id='9d7dfed9-ad28-5164-b454-afb93456f949' AND e.command_receipt_id=q.id AND e.owner_module_id=q.owner_module_id
  AND e.aggregate_kind='CustomerProfile' AND e.aggregate_id=c.id::text AND e.previous_revision IS NULL AND e.committed_revision=0
  AND e.action=q.operation AND e.decision_ref='customer-controls-v1' AND e.evidence_schema_version='1'
  AND e.evidence_schema_id='urn:workinants:database-review:owner-evidence:v1#/$defs/CustomerProfile'
  AND e.evidence_body='{"schema":"database-owner-evidence.v1","owner":"customer_buyer_profile","model":"CustomerProfile","primaryKey":{"id":"1231a676-4ed8-535a-8c2b-8243befd0ab8"},"prior":null,"committed":{"id":"1231a676-4ed8-535a-8c2b-8243befd0ab8","userId":"e76d13b8-de8f-509f-85df-016eda48ec10","status":"active","revision":"0","privacyGeneration":"0"},"decisionRef":"customer-controls-v1"}'::jsonb AND e.evidence_digest=encode(sha256(convert_to(e.evidence_body::text,'UTF8')),'hex')
 WHERE c.id='1231a676-4ed8-535a-8c2b-8243befd0ab8' AND c.user_id='e76d13b8-de8f-509f-85df-016eda48ec10' AND c.status='active' AND c.revision=0 AND c.privacy_generation=0
  AND c.display_name IS NULL AND c.avatar_media_id IS NULL AND c.city IS NULL AND c.state IS NULL AND c.country IS NULL AND c.archived_at IS NULL
